.tb-side{text-align:right;display:flex;flex-direction:column;gap:2px;font:500 12px ui-monospace,Menlo,Consolas,monospace;color:#8DA2B2;white-space:nowrap}
.tb-side b{font-size:14px;color:#E4EDF3}
.tb-card.cci_confirmed{border-color:rgba(255,107,94,.45)}
.tb-card.cci_confirmed .tb-bar{background:#FF6B5E}
@keyframes tb-pulse{0%,100%{box-shadow:inset 0 0 0 1px rgba(255,107,94,0);background-color:#0F1F2C}50%{box-shadow:inset 0 0 0 1px rgba(255,107,94,.85),inset 0 0 22px rgba(255,107,94,.16);background-color:#16212E}}
@keyframes tb-bar{0%,100%{opacity:1}50%{opacity:.45}}
.tb-card.cci_confirmed{animation:tb-pulse 2s ease-in-out infinite}
.tb-card.cci_confirmed .tb-bar{animation:tb-bar 2s ease-in-out infinite}
@media (prefers-reduced-motion:reduce){.tb-card.cci_confirmed,.tb-card.cci_confirmed .tb-bar{animation:none!important}}
.tb-card.cci_confirmed .tb-verdict{color:#FF8A80}
.tb-card.cci_confirmed .tb-v::before{content:"CCI CONFIRMED"}
.tb-card.dual_unexplained .tb-bar{background:#E0A458}
.tb-card.dual_unexplained .tb-verdict{color:#E0A458}
.tb-card.dual_unexplained .tb-v::before{content:"DUAL UNEXPLAINED"}
.tb-card.dual_ducting_unknown .tb-bar{background:#A88A4A}
.tb-card.dual_ducting_unknown .tb-verdict{color:#D2B270}
.tb-card.dual_ducting_unknown .tb-v::before{content:"DUCTING UNKNOWN"}
.tb-card.unpaired .tb-v::before{content:"UNPAIRED"}
.tb-card.single_side .tb-v::before{content:"SINGLE SIDE"}
.tb-strength{text-transform:uppercase}
.tb-card.dual_unexplained .tb-why::before{content:"No co-channel path is ducting: check the site"}
.tb-card.dual_ducting_unknown .tb-why::before{content:"Ducting can't be judged right now: check weather data"}
.tb-card.single_side .tb-why::before{content:"One side only, the other is clean: check the demod"}
.tb-card.unpaired .tb-why::before{content:"The other side can't be judged"}
.tb-empty{color:#8DA2B2;font-size:13px;padding:8px 4px}
</style>
<div class="tb-deck">
  <div class="tb-head"><b>Open episodes</b><span>LAST 6 MIN · NEWEST EVENT PER EPISODE</span></div>
  <div class="tb-list">
  {{#each metrics}}
  {{#compare metrics.2.value "!=" "clear"}}
  <div class="tb-card {{metrics.1.value}}">
    <div class="tb-bar"></div>
    <div class="tb-main">
      {{#if metrics.11.raw}}<div class="tb-where"><span>{{#each metrics.11.raw}}{{this}}{{#unless @last}} / {{/unless}}{{else}}{{metrics.11.value}}{{/each}}</span><span class="tb-site">{{metrics.8.value}} · RF {{metrics.9.value}}</span></div>{{else}}<div class="tb-where">{{metrics.8.value}} · RF {{metrics.9.value}}</div>{{/if}}
      <div class="tb-verdict"><span class="tb-v"></span>{{#if metrics.3.raw}} · <span class="tb-strength">{{metrics.3.value}}</span>{{/if}}</div>
      <div class="tb-detail">{{#if metrics.3.raw}}Likely interferer {{metrics.4.value}}, {{metrics.5.value}} mi{{else}}<span class="tb-why"></span>{{/if}}{{#if metrics.10.raw}} · power {{metrics.10.value}}{{/if}}</div>
    </div>
    <div class="tb-side"><b>{{#compare metrics.7.raw "<" 60}}{{math metrics.7.raw "-" (math metrics.7.raw "%" 1)}} s{{else}}{{#compare metrics.7.raw "<" 3600}}{{math (math metrics.7.raw "/" 60) "-" (math (math metrics.7.raw "/" 60) "%" 1)}} m {{math (math metrics.7.raw "%" 60) "-" (math (math metrics.7.raw "%" 60) "%" 1)}} s{{else}}{{math (math metrics.7.raw "/" 3600) "-" (math (math metrics.7.raw "/" 3600) "%" 1)}} h {{math (math (math metrics.7.raw "%" 3600) "/" 60) "-" (math (math (math metrics.7.raw "%" 3600) "/" 60) "%" 1)}} m{{/compare}}{{/compare}}</b><span>at last event</span><span>since {{metrics.6.value}}</span></div>
  </div>
  {{/compare}}
  {{/each}}
  </div>
</div>
", "template": "{}"}}

