   "transform": [
    {
     "type": "formula",
     "as": "code",
     "expr": "datum._source.code"
    },
    {
     "type": "formula",
     "as": "tz",
     "expr": "zoneLrf[datum.code] || zone[datum._source.state] || 'AK, HI, PR'"
    },
    {
     "type": "formula",
     "as": "climate",
     "expr": "climateLrf[datum.code] || climate[datum._source.state] || 'AK, HI, PR'"
    }
   ]
