  {
   "name": "epRaw",
   "format": {
    "property": "aggregations.l.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "l": {
       "terms": {
        "field": "tropobeat.lrf_codes",
        "size": 500
       },
       "aggs": {
        "e": {
         "terms": {
          "field": "tropobeat.correlation.episode.id",
          "size": 2000
         },
         "aggs": {
          "p": {
           "terms": {
            "field": "tropobeat.correlation.episode.peak_state",
            "size": 1
           }
          }
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "eps",
   "source": "epRaw",
   "transform": [
    {
     "type": "flatten",
     "fields": [
